How can I create a C# algorithm that calculates the mean, median, and mode of a dataset that may have outliers and varying data types, and also a visualization tool that shows the distribution of the dataset with bar and line charts? Additionally, can you provide an example of how the algorithm would handle the following XML dataset? 
```C#
using System;
using System.Collections.Generic;
using System.Linq;
using System.Xml.Linq;
using System.Windows.Forms.DataVisualization.Charting;
namespace DataAnalysis
{
    class Program
    {
        static void Main(string[] args)
        {
            // Load the XML dataset
            XElement data = XElement.Load("data.xml");
            // Parse the values from the XML into a list of doubles
            List<double> values = data.Elements("value").Select(e => (double)e).ToList();
            // Calculate the mean
            double mean = values.Average();
            // Calculate the median
            double median = values.OrderBy(v => v).Skip(values.Count / 2).First();
            // Calculate the mode
            double mode = values.GroupBy(v => v).OrderByDescending(g => g.Count()).First().Key;
            // Print the results
            Console.WriteLine("Mean: " + mean);
            Console.WriteLine("Median: " + median);
            Console.WriteLine("Mode: " + mode);
            // Create a chart to display the distribution of the dataset
            Chart chart = new Chart();
            chart.ChartAreas.Add(new ChartArea());
            // Create a bar chart of the data
            Series barSeries = new Series();
            barSeries.ChartType = SeriesChartType.Column;
            barSeries.Points.DataBindY(values);
            chart.Series.Add(barSeries);
            // Create a line chart of the mean, median, and mode
            Series lineSeries = new Series();
            lineSeries.ChartType = SeriesChartType.Line;
            lineSeries.Points.Add(new DataPoint(0, mean));
            lineSeries.Points.Add(new DataPoint(values.Count - 1, mean));
            lineSeries.Points.Add(new DataPoint(0, median));
            lineSeries.Points.Add(new DataPoint(values.Count - 1, median));
            lineSeries.Points.Add(new DataPoint(0, mode));
            lineSeries.Points.Add(new DataPoint(values.Count - 1, mode));
            chart.Series.Add(lineSeries);
            // Display the chart
            chart.Dock = DockStyle.Fill;
            Form form = new Form();
            form.Controls.Add(chart);
            form.ShowDialog();
        }
    }
}
```
