package main
import (
    "fmt"
    "github.com/dimiro1/doublemetaphone"
)
func main() {
    word := "cat"
    metaphones := doublemetaphone.New(word)
    primary, secondary := metaphones.Process()
    // Find words that have the same primary or secondary metaphone code
    words := []string{"bat", "rat", "hat", "chat", "catch", "cab", "cut"}
    for _, w := range words {
        m := doublemetaphone.New(w)
        p, s := m.Process()
        if p == primary || s == secondary {
            fmt.Printf("%s rhymes with %s\n", w, word)
        }
    }
}
