package main
import (
    "encoding/json"
    "fmt"
    "os"
)
type Data struct {
    Variable1 string `json:"variable1"`
    Variable2 string `json:"variable2"`
    Variable3 string `json:"variable3"`
}
type JSONData struct {
    Data []Data `json:"data"`
}
func main() {
    file, err := os.Open("example.json")
    if err != nil {
        fmt.Println(err)
    }
    defer file.Close()
    decoder := json.NewDecoder(file)
    jsonData := JSONData{}
    err = decoder.Decode(&jsonData)
    if err != nil {
        fmt.Println(err)
    }
    for _, data := range jsonData.Data {
        fmt.Println(data.Variable1, data.Variable2, data.Variable3)
