#include <map>
std::string translate(const std::string& phrase, const std::map<std::string, std::string>& dictionary)
{
    std::string result = "";
    std::string word = "";
    for (auto c : phrase)
    {
        if (c == ' ')
        {
            result += dictionary[word] + " ";
            word = "";
        }
        else
        {
            word += c;
        }
    }
    result += dictionary[word];
    return result;
}
