setGrindSize("fine");
// Fill the portafilter with freshly ground coffee
fillPortafilter();
// Tamp the coffee down firmly and evenly
tampCoffee();
// Start the brewing process
startBrewing();
// Brew for 25 seconds
brewFor(25);
// Pour the shot into a preheated espresso cup
pourShot();
```
