        for (double x = 0; x < 1; x += epsilon) {
            if (!isRational(x)) {
                System.out.println(x);
            }
        }
    }
    public static boolean isRational(double x) {
        double epsilon = 0.0000001;
        for (int i = 1; i < 100000; i++) {
            double r = (double) i / (double) (i + 1);
            if (Math.abs(x - r) < epsilon) {
                return true;
            }
        }
        return false;
    }
}
```
