// Define a list of known satirical sources and their corresponding tone
Dictionary<string, string> satiricalSources = new Dictionary<string, string> {
    { "The Onion", "sarcastic" },
    { "Clickhole", "parodic" },
    { "Reductress", "ironic" }
};
// Analyze the input text and determine if it contains any science keywords
bool containsScienceKeywords = false;
foreach (string keyword in scienceKeywords) {
    if (inputText.Contains(keyword)) {
        containsScienceKeywords = true;
        break;
    }
}
// Determine the tone of the input text based on known satirical sources
string tone = "genuine";
foreach (KeyValuePair<string, string> source in satiricalSources) {
    if (inputText.Contains(source.Key)) {
        tone = source.Value;
        break;
    }
}
// Provide an explanation for the classification
